create table transactions (id uuid primary key, transaction_id varchar(64) not null unique, merchant_id varchar(128) not null, amount_minor bigint not null check (amount_minor >= 0), currency varchar(3) not null, status varchar(16) not null, stripe_charge_id varchar(255), fraud_score double precision, fraud_decision varchar(16), created_at timestamptz not null, updated_at timestamptz not null); create index idx_transactions_merchant_created on transactions (merchant_id, created_at);
